{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-LirH9r/src/util.js","content":"/**
 * Small helpers shared by the parser and the renderers: cursor movement
 * within a single line, and the code-point key ordering the spec requires
 * for both output modes.
 */

export function skipWs(line, pos) {
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) pos++
  return pos
}

// True once nothing meaningful is left on the line: real end of line, or a
// comment start reached at a token boundary (see cli.js's callers for the
// one place - inside a bareword scan - where a `#`/`;` does not count).
export function atEnd(line, pos) {
  return pos >= line.length || line[pos] === '#' || line[pos] === ';'
}

export function cmpCodePoint(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

export function err(ctx, reason) {
  return new ParseError(ctx.lineNo, reason)
}
"}

