 * Scanners for the two quoted-string forms. Both are single-line: a string
 * that never finds its closing quote before the line ends is unterminated.
 */

import { err } from './util.js'

const SIMPLE_ESCAPES = {
  '"': '"',
  '\\': '\\',
  n: '\n',
  t: '\t',
  r: '\r',
  0: '\0',
}

export function scanBasicString(ctx, pos) {
  const line = ctx.line
  let i = pos + 1
  let out = ''
  while (true) {
    if (i >= line.length) throw err(ctx, 'unterminated string')
    const c = line[i]
    if (c === '"') return { text: out, pos: i + 1 }
    if (c === '\\') {
      const e = line[i + 1]
      if (e === undefined) throw err(ctx, 'unterminated string')
      if (e === 'u') {
        const hex = line.slice(i + 2, i + 6)
        if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
          out += String.fromCharCode(parseInt(hex, 16))
          i += 6
        } else {
          throw err(ctx, 'invalid escape \\u')
        }
      } else if (Object.prototype.hasOwnProperty.call(SIMPLE_ESCAPES, e)) {
        out += SIMPLE_ESCAPES[e]
        i += 2
      } else {
        throw err(ctx, `invalid escape \\${e}`)
      }
    } else {
      out += c
      i++
    }
  }
}

export function scanLiteralString(ctx, pos) {
  const line = ctx.line
  let i = pos + 1
  const start = i
  while (true) {
    if (i >= line.length) throw err(ctx, 'unterminated string')
    if (line[i] === "'") return { text: line.slice(start, i), pos: i + 1 }
    i++
  }
}
"}

