 * Names and dotted names: `A-Za-z0-9_-` bare words or quoted strings,
 * joined by `.` with optional surrounding spaces and tabs.
 */

import { skipWs, err } from './util.js'
import { scanBasicString, scanLiteralString } from './strings.js'

const BARE_NAME_CHAR = /[A-Za-z0-9_-]/

export function parseName(ctx, pos) {
  const line = ctx.line
  pos = skipWs(line, pos)
  if (pos >= line.length) throw err(ctx, 'expected a name')
  const c = line[pos]
  if (c === '"') {
    const { text, pos: p2 } = scanBasicString(ctx, pos)
    return { name: text, pos: p2 }
  }
  if (c === "'") {
    const { text, pos: p2 } = scanLiteralString(ctx, pos)
    return { name: text, pos: p2 }
  }
  const start = pos
  while (pos < line.length && BARE_NAME_CHAR.test(line[pos])) pos++
  if (pos === start) throw err(ctx, 'expected a name')
  return { name: line.slice(start, pos), pos }
}

export function parseDottedName(ctx, pos) {
  const line = ctx.line
  const segments = []
  const first = parseName(ctx, pos)
  segments.push(first.name)
  pos = first.pos
  while (true) {
    const afterWs = skipWs(line, pos)
    if (line[afterWs] !== '.') break
    const nameStart = skipWs(line, afterWs + 1)
    const next = parseName(ctx, nameStart)
    segments.push(next.name)
    pos = next.pos
  }
  return { segments, pos }
}
"}

