{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-LirH9r/src/values.js","content":"/**
 * Value parsing: booleans, numbers, both string forms, arrays and inline
 * tables. Arrays and inline tables recurse back into `parseValue`.
 */

import { skipWs, atEnd, err } from './util.js'
import { scanBasicString, scanLiteralString } from './strings.js'
import { parseDottedName } from './names.js'
import { makeTable, walkToParent } from './tables.js'

const DIGITS = '\\d+(?:_\\d+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`)

// The characters that end an unquoted (bareword) value token. Anything
// else - including `#` or `;` immediately following, with no separating
// whitespace - is swallowed into the token, per the spec's rule that a
// value a comment marker "runs into" is invalid rather than commented out.
const BAREWORD_TERMINATORS = new Set([' ', '\t', ',', ']', '}'])

function classifyBareword(text) {
  if (text === 'true') return { type: 'boolean', value: true }
  if (text === 'false') return { type: 'boolean', value: false }
  if (INT_RE.test(text)) return { type: 'integer', value: Number(text.replace(/_/g, '')) }
  if ((text.includes('.') || /[eE]/.test(text)) && FLOAT_RE.test(text)) {
    return { type: 'float', value: Number(text.replace(/_/g, '')) }
  }
  return null
}

export function parseValue(ctx, pos, prefix = []) {
  const line = ctx.line
  pos = skipWs(line, pos)
  if (atEnd(line, pos)) throw err(ctx, 'expected a value')
  const c = line[pos]
  if (c === '"') {
    const { text, pos: p2 } = scanBasicString(ctx, pos)
    return { node: { type: 'string', value: text }, pos: p2 }
  }
  if (c === "'") {
    const { text, pos: p2 } = scanLiteralString(ctx, pos)
    return { node: { type: 'string', value: text }, pos: p2 }
  }
  if (c === '[') return parseArray(ctx, pos)
  if (c === '{') return parseInlineTable(ctx, pos, prefix)

  const start = pos
  while (pos < line.length && !BAREWORD_TERMINATORS.has(line[pos])) pos++
  const text = line.slice(start, pos)
  const cls = classifyBareword(text)
  if (!cls) throw err(ctx, `invalid value ${text}`)
  return { node: cls, pos }
}

export function parseArray(ctx, pos) {
  const line = ctx.line
  pos++ // consume '['
  const items = []
  pos = skipWs(line, pos)
  if (atEnd(line, pos)) throw err(ctx, 'unterminated array')
  if (line[pos] === ']') return { node: { type: 'array', items }, pos: pos + 1 }
  while (true) {
    const r = parseValue(ctx, pos, [])
    items.push(r.node)
    pos = skipWs(line, r.pos)
    if (atEnd(line, pos)) throw err(ctx, 'unterminated array')
    if (line[pos] === ',') {
      pos = skipWs(line, pos + 1)
      if (atEnd(line, pos)) throw err(ctx, 'unterminated array')
      if (line[pos] === ']') return { node: { type: 'array', items }, pos: pos + 1 }
      continue
    }
    if (line[pos] === ']') return { node: { type: 'array', items }, pos: pos + 1 }
    throw err(ctx, 'unterminated array')
  }
}

export function parseInlineTable(ctx, pos, prefix) {
  const line = ctx.line
  pos++ // consume '{'
  const table = makeTable()
  table.path = prefix
  pos = skipWs(line, pos)
  if (atEnd(line, pos)) throw err(ctx, 'unterminated inline table')
