 * Top-level document parsing: splits the input into lines and turns each
 * non-blank, non-comment line into either a table header or a key
 * assignment against the currently-open table.
 */

import { skipWs, atEnd, err } from './util.js'
import { parseDottedName } from './names.js'
import { parseValue } from './values.js'
import { makeTable, walkToParent } from './tables.js'

export { ParseError } from './util.js'

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  root.path = []
  const state = { current: root }

  for (let i = 0; i < lines.length; i++) {
    processLine(lines[i], i + 1, root, state)
  }
  return root
}

function processLine(line, lineNo, root, state) {
  const firstIdx = line.search(/[^ \t]/)
  if (firstIdx === -1) return // blank line
  const c0 = line[firstIdx]
  if (c0 === '#' || c0 === ';') return // full-line comment

  const ctx = { line, lineNo }
  if (c0 === '[') {
    handleHeader(ctx, firstIdx, root, state)
  } else {
    handleAssignment(ctx, firstIdx, state.current)
  }
}

function handleHeader(ctx, pos, root, state) {
  const line = ctx.line
  let isArray = false
  let p = pos + 1
  if (line[p] === '[') {
    isArray = true
    p++
  }
  const { segments, pos: p2 } = parseDottedName(ctx, p)
  let p3 = skipWs(line, p2)
  if (isArray) {
    if (line[p3] !== ']' || line[p3 + 1] !== ']') throw err(ctx, 'unterminated table header')
    p3 += 2
  } else {
    if (line[p3] !== ']') throw err(ctx, 'unterminated table header')
    p3 += 1
  }
  const p4 = skipWs(line, p3)
  if (!atEnd(line, p4)) throw err(ctx, 'trailing text after a table header')

  const { parent, final } = walkToParent(ctx, root, segments, [])
  const fullPath = segments.join('.')

  if (isArray) {
    let node = parent.value.get(final)
    if (node === undefined) {
      node = { type: 'array', items: [], kind: 'aot' }
      parent.value.set(final, node)
    } else if (!(node.type === 'array' && node.kind === 'aot')) {
      throw err(ctx, `${fullPath} is not an array of tables`)
    }
    const table = makeTable()
    table.path = segments
    node.items.push(table)
    state.current = table
  } else {
    let node = parent.value.get(final)
    if (node === undefined) {
      node = makeTable()
      node.path = segments
      parent.value.set(final, node)
    } else if (node.type !== 'table') {
      throw err(ctx, `${fullPath} is not a table`)
    } else if (node.openedByHeader) {
      throw err(ctx, `table ${fullPath} is defined twice`)
    }
    node.openedByHeader = true
    state.current = node
  }
