 * Renders a parsed document as canonical JSON (two-space indent, keys in
 * ascending code-point order) or as a flat `keys` listing.
 */

import { cmpCodePoint } from './util.js'

function sortedKeys(table) {
  return [...table.value.keys()].sort(cmpCodePoint)
}

function renderJsonNode(node, indent) {
  const pad = '  '.repeat(indent)
  const padIn = '  '.repeat(indent + 1)
  switch (node.type) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const parts = keys.map(
        (k) => `${padIn}${JSON.stringify(k)}: ${renderJsonNode(node.value.get(k), indent + 1)}`
      )
      return `{\n${parts.join(',\n')}\n${pad}}`
    }
    case 'array': {
      if (node.items.length === 0) return '[]'
      const parts = node.items.map((item) => `${padIn}${renderJsonNode(item, indent + 1)}`)
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    default:
      return JSON.stringify(node.value)
  }
}

export function renderJson(root) {
  return renderJsonNode(root, 0) + '\n'
}

function walkKeys(path, node, lines) {
  lines.push(`${path} ${node.type}`)
  if (node.type === 'table') {
    for (const k of sortedKeys(node)) walkKeys(`${path}.${k}`, node.value.get(k), lines)
  } else if (node.type === 'array') {
    node.items.forEach((item, i) => walkKeys(`${path}[${i}]`, item, lines))
  }
}

export function renderKeys(root) {
  const lines = []
  for (const k of sortedKeys(root)) walkKeys(k, root.value.get(k), lines)
  return lines.length ? lines.join('\n') + '\n' : ''
}
"}

